#!/bin/bash
# The candidate's build artifacts, all UNSIGNED (no keystore is read):
#   1. the agent bundle (standalone/build-bundle.mjs, esbuild) for the BASE (pristine) and the CANDIDATE (tree)
#   2. classes.dex (build.sh step 3: javac --release 17 vs android-35 + 32 slot classes, d8 --min-api 34) for the BASE (must equal
#      the INSTALLED dex 8bb873a0...), the CANDIDATE (independent), and the CANDIDATE + the phone-dns RelayDial patch (composed)
#   3. installed-APK-compatible candidate APKs: the installed APK with ONLY classes.dex and the rebuilt agent bundle files replaced
#      (build.json, idle-app.wasm, native libraries, manifest, resources unchanged), aligned as build.sh aligns (zipalign -P 16 -f 4)
set -euo pipefail
H=/home/steven/Documents/Codex/2026-10-18/wo/work/android-independent-host; P=/home/steven/Documents/Codex/2026-10-18/wo/work/phone-dns-recovery
SDK=/home/steven/Android/Sdk; BT=$SDK/build-tools/35.0.0; AJ=$SDK/platforms/android-35/android.jar
O=$H/artifacts; rm -rf $O/bundle-* $O/dex-* $O/apk-*; mkdir -p $O
IDLE=$O/installed/assets/agent/idle-app.wasm
for side in base candidate; do
  T=$H/pristine; [ $side = candidate ] && T=$H/tree
  (cd $T && node shielded/anchor/avf/standalone/build-bundle.mjs $O/bundle-$side $IDLE) > $O/bundle-$side.log 2>&1 || { echo "bundle $side FAILED"; cat $O/bundle-$side.log; exit 1; }
  echo "bundle $side: exit 0"; sed 's/^/   /' $O/bundle-$side.log
done
dexof() {   # <name> <host/app dir>
  local S=$O/dex-$1; mkdir -p $S/classes $S/dex $S/gen
  for k in $(seq 1 32); do printf '/* generated by build.sh: slot %s, its own process (":slot%s") */\npackage host.enclave.anchor.avf;\npublic class AnchorServiceSlot%s extends AnchorService { }\n' "$k" "$k" "$k" > $S/gen/AnchorServiceSlot$k.java; done
  javac --release 17 -Xlint:-options -cp "$AJ" -d $S/classes $2/*.java $S/gen/*.java > $S/javac.log 2>&1 || { echo "$1: javac FAILED"; cat $S/javac.log; exit 1; }
  "$BT/d8" --min-api 34 --output $S/dex $S/classes/host/enclave/anchor/avf/*.class > $S/d8.log 2>&1 || { echo "$1: d8 FAILED"; cat $S/d8.log; exit 1; }
  echo "dex $1: javac+d8 exit 0, classes.dex $(sha256sum $S/dex/classes.dex | cut -c1-64) ($(stat -c %s $S/dex/classes.dex) B)"
}
dexof base $H/pristine/shielded/anchor/avf/host/app
INST=$(sha256sum $O/installed/classes.dex | cut -c1-64); [ "$(sha256sum $O/dex-base/dex/classes.dex | cut -c1-64)" = "$INST" ] && echo "   base dex == INSTALLED dex ($INST)" || { echo "   base dex != installed dex: the base is not the deployed source"; exit 1; }
dexof candidate $H/tree/shielded/anchor/avf/host/app
C=$(mktemp -d); trap 'rm -rf $C' EXIT; mkdir -p $C/x/shielded/anchor/avf/host && cp -r $H/tree/shielded/anchor/avf/host/app $C/x/shielded/anchor/avf/host/app
( cd $C/x && patch -s -p1 < $P/claude/host-relaydial.patch ) || { echo "the RelayDial patch does not apply on the candidate"; exit 1; }
echo "   RelayDial patch (phone-dns-recovery, $(sha256sum $P/claude/host-relaydial.patch | cut -c1-16)) applies cleanly on the candidate"
dexof candidate-relaydial $C/x/shielded/anchor/avf/host/app
for v in candidate candidate-relaydial; do
  python3 - "$O" "$v" <<'PY'
import sys, zipfile, hashlib
O, v = sys.argv[1], sys.argv[2]
src = zipfile.ZipFile('/home/steven/Documents/Codex/2026-10-18/wo/work/phone-dns-recovery/claude/installed-host.apk')
repl = {'classes.dex': open(f'{O}/dex-{v}/dex/classes.dex', 'rb').read()}
for f in ['standalone.mjs', 'net-child.mjs', 'windows-circuit-worker.mjs', 'adb-self.mjs']:
    repl[f'assets/agent/{f}'] = open(f'{O}/bundle-candidate/{f}', 'rb').read()
dst = zipfile.ZipFile(f'{O}/apk-{v}-unaligned.apk', 'w')
for i in src.infolist():
    if i.filename.startswith('META-INF/') and i.filename.rsplit('.', 1)[-1] in ('SF', 'RSA', 'EC', 'DSA', 'MF'): continue
    data = repl.get(i.filename, src.read(i))
    zi = zipfile.ZipInfo(i.filename, date_time=i.date_time); zi.external_attr = i.external_attr
    dst.writestr(zi, data, compress_type=i.compress_type)
dst.close()
a, b = zipfile.ZipFile(src.filename), zipfile.ZipFile(f'{O}/apk-{v}-unaligned.apk')
ha = {i.filename: hashlib.sha256(a.read(i)).hexdigest() for i in a.infolist()}; hb = {i.filename: hashlib.sha256(b.read(i)).hexdigest() for i in b.infolist()}
diff = sorted(n for n in set(ha) | set(hb) if ha.get(n) != hb.get(n))
assert set(diff) <= set(repl), diff
print(f'apk {v}: entries changed vs installed: {diff}')
PY
  "$BT/zipalign" -P 16 -f 4 $O/apk-$v-unaligned.apk $O/apk-$v-unsigned.apk && "$BT/zipalign" -c -P 16 4 $O/apk-$v-unsigned.apk && rm $O/apk-$v-unaligned.apk
  echo "   apk-$v-unsigned.apk $(sha256sum $O/apk-$v-unsigned.apk | cut -c1-64) (zipalign -c -P 16 4: ok; NOT signed)"
done
echo "ALL BUILDS DONE"
